pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response time is less than 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Response contains tool objects with required fields", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.length).to.be.above(0);
    jsonData.forEach( (tool)=> {
        pm.expect(tool).to.have.property('id');
        pm.expect(tool).to.have.property('name');
        pm.expect(tool).to.have.property('category');
        pm.expect(tool).to.have.property('inStock');
    });
});
